package com.lmspilot.reporting.api;import com.lmspilot.contracts.Permissions;import com.lmspilot.reporting.domain.*;import com.lmspilot.support.api.ApiException;import com.lmspilot.support.security.CurrentUser;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;@Service public class KpiReportingService{private final LearnerCourseReadModelRepository repo;private final EnrollmentScopeClient scope;public KpiReportingService(LearnerCourseReadModelRepository r,EnrollmentScopeClient s){repo=r;scope=s;}@Transactional(readOnly=true)public LearningKpiResponse summary(ReportScope s,UUID course){return aggregate(s,course,rows(s).stream().filter(x->course==null||x.getCourseId().equals(course)).toList());}@Transactional(readOnly=true)public List<CourseKpiRow>byCourse(ReportScope s){Map<UUID,List<LearnerCourseReadModel>>g=new HashMap<>();for(var r:rows(s))g.computeIfAbsent(r.getCourseId(),k->new ArrayList<>()).add(r);List<CourseKpiRow>out=new ArrayList<>();g.forEach((id,v)->{var a=aggregate(s,id,v);Instant last=v.stream().map(LearnerCourseReadModel::getLastActivityAt).filter(Objects::nonNull).max(Comparator.naturalOrder()).orElse(null);out.add(new CourseKpiRow(id,a.totalEnrollments(),a.completed(),a.overdue(),a.completionRate(),a.passRate(),a.averageProgress(),a.averageScore(),last));});out.sort(Comparator.comparingInt(CourseKpiRow::overdue).reversed().thenComparing(Comparator.comparingInt(CourseKpiRow::totalEnrollments).reversed()).thenComparing(CourseKpiRow::courseId));return out;}private List<LearnerCourseReadModel>rows(ReportScope s){validate(s);return switch(s){case SELF->repo.findAllByUserId(CurrentUser.id());case ASSIGNED->{Set<UUID>ids=scope.assignedDeliveryIds(CurrentUser.id());yield ids.isEmpty()?List.of():repo.findAllByClassIdIn(ids);}case SYSTEM->repo.findAll();};}private LearningKpiResponse aggregate(ReportScope s,UUID cid,List<LearnerCourseReadModel>r){Instant now=Instant.now(),active=now.minusSeconds(30L*86400),soon=now.plusSeconds(7L*86400);int completed=(int)r.stream().filter(LearnerCourseReadModel::isCompleted).count(),overdue=(int)r.stream().filter(x->!x.isCompleted()&&x.getDueAt()!=null&&x.getDueAt().isBefore(now)).count(),progress=(int)r.stream().filter(x->!x.isCompleted()&&x.getProgressPercent()>0&&(x.getDueAt()==null||!x.getDueAt().isBefore(now))).count(),not=r.size()-completed-overdue-progress,due=(int)r.stream().filter(x->!x.isCompleted()&&x.getDueAt()!=null&&!x.getDueAt().isBefore(now)&&!x.getDueAt().isAfter(soon)).count();var graded=r.stream().filter(x->x.getPassed()!=null).toList();int passed=(int)graded.stream().filter(x->Boolean.TRUE.equals(x.getPassed())).count(),failed=graded.size()-passed,act=(int)r.stream().filter(x->x.getLastActivityAt()!=null&&!x.getLastActivityAt().isBefore(active)).count();double avgp=round(r.stream().mapToInt(LearnerCourseReadModel::getProgressPercent).average().orElse(0));var scores=r.stream().map(LearnerCourseReadModel::getLastScore).filter(Objects::nonNull).mapToDouble(Double::doubleValue).toArray();Double avgs=scores.length==0?null:round(Arrays.stream(scores).average().orElse(0));return new LearningKpiResponse(s,cid,r.size(),not,progress,completed,overdue,due,passed,failed,act,pct(completed,r.size()),pct(passed,graded.size()),avgp,avgs,now);}private void validate(ReportScope s){if(s==ReportScope.SYSTEM&&!CurrentUser.hasRole("ADMIN")&&!CurrentUser.globalAuthorities().contains(Permissions.REPORTS_KPI_READ)&&!CurrentUser.globalAuthorities().contains(Permissions.REPORTS_READ_SCOPE))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_SCOPE_DENIED","Chỉ quản trị hệ thống được xem KPI toàn hệ thống");if(s==ReportScope.ASSIGNED&&!CurrentUser.authorities().contains(Permissions.REPORTS_KPI_READ)&&!CurrentUser.authorities().contains(Permissions.REPORTS_READ_SCOPE)&&!CurrentUser.authorities().contains(Permissions.REPORTS_READ))throw new ApiException(HttpStatus.FORBIDDEN,"REPORT_SCOPE_DENIED","Không có quyền xem KPI theo phạm vi được giao");}private double pct(int p,int t){return t==0?0:round(p*100d/t);}private double round(double v){return Math.round(v*100d)/100d;}}
